import React from "react";
import { motion } from "framer-motion";
import { useTranslation } from "react-i18next";

const Testimonials = () => {
  const { t } = useTranslation();

  const testimonials = [
    {
      text: t("testimonials.0.text"),
      author: t("testimonials.0.author"),
      detail: t("testimonials.0.detail"),
    },
    {
      text: t("testimonials.1.text"),
      author: t("testimonials.1.author"),
      detail: t("testimonials.1.detail"),
    },
    {
      text: t("testimonials.2.text"),
      author: t("testimonials.2.author"),
      detail: t("testimonials.2.detail"),
    },
  ];

  // Ustawienia animacji
  const fadeIn = {
    hidden: { opacity: 0, y: 50 },
    visible: { opacity: 1, y: 0, transition: { duration: 0.8 } },
  };

  return (
    <section className="bg-gray-900 text-white py-20">
      <div className="max-w-6xl mx-auto px-6 sm:px-12">
        {/* Nagłówek z pionową kreską */}
        <motion.div
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true }}
          className="flex items-center mb-16"
        >
          <div className="h-12 w-1 bg-gray-500 mr-4"></div>
          <h2 className="text-4xl sm:text-5xl font-light leading-tight font-sans">
            {t("testimonials.heading")}
          </h2>
        </motion.div>

        {/* Treści testimoniali */}
        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-16">
          {testimonials.map((testimonial, index) => (
            <motion.div
              key={index}
              variants={fadeIn}
              initial="hidden"
              whileInView="visible"
              viewport={{ once: true }}
              className="space-y-6 text-left"
            >
              <p className="text-base sm:text-lg leading-relaxed text-gray-300 font-sans">
                {testimonial.text}
              </p>
              <div className="text-lg sm:text-xl font-semibold font-playfair">
                {testimonial.author}
              </div>
              <div className="text-sm sm:text-base text-gray-500 font-sans">
                {testimonial.detail}
              </div>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default Testimonials;





