import React from "react";
import { Link } from "react-router-dom";
import { useTranslation } from "react-i18next";

const Footer = () => {
  const { t } = useTranslation();

  return (
    <footer className="bg-black text-gray-400 py-8">
      <div className="max-w-6xl mx-auto px-6 flex flex-col items-center space-y-4 text-center">
        {/* Logo */}
        <div className="text-lg sm:text-xl lg:text-2xl font-semibold text-gray-300 font-playfair">
          CraftedWebs
        </div>

        {/* Legal Information */}
        <div className="text-sm sm:text-base text-gray-400 flex flex-wrap items-center justify-center space-x-4 font-sans">
          <Link to="/polityka-prywatnosci" className="hover:text-white">
            {t("footer.privacyPolicy")}
          </Link>
          <span className="hidden sm:block text-gray-500">|</span>
          <Link to="/regulamin" className="hover:text-white">
            {t("footer.termsOfService")}
          </Link>
          <span className="hidden sm:block text-gray-500">|</span>
          <Link to="/cookies" className="hover:text-white">
            {t("footer.cookies")}
          </Link>
        </div>

        {/* Copyright */}
        <div className="text-xs sm:text-sm text-gray-500 font-sans">
          &copy; {new Date().getFullYear()} CraftedWebs. {t("footer.copyright")}
        </div>
      </div>
    </footer>
  );
};

export default Footer;









