import React, { useState } from "react";
import { Link } from "react-router-dom";
import { useTranslation } from "react-i18next";
import { IoIosArrowDown, IoIosArrowUp } from "react-icons/io";
import { FiMenu, FiX } from "react-icons/fi";
import plFlag from "./images/icons/pl.png";
import enFlag from "./images/icons/en.png";
import ukrFlag from "./images/icons/ukr.png";

const Header = () => {
  const { t, i18n } = useTranslation();
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isServicesOpen, setIsServicesOpen] = useState(false);
  const [isLangOpen, setIsLangOpen] = useState(false);
  const [language, setLanguage] = useState(localStorage.getItem("language") || "PL");

  const toggleMenu = () => {
    setIsMenuOpen((prevState) => !prevState);
    setIsServicesOpen(false);
    setIsLangOpen(false);
  };

  const toggleServices = () => {
    setIsServicesOpen((prevState) => !prevState);
  };

  const toggleLang = () => {
    setIsLangOpen((prevState) => !prevState);
  };

  const changeLanguage = (lang) => {
    setLanguage(lang);
    localStorage.setItem("language", lang);
    i18n.changeLanguage(lang);
    setIsLangOpen(false);
  };

  return (
    <header className="bg-[#8b9694] text-white fixed top-0 w-full z-50 shadow-md py-4">
      <div className="max-w-screen-2xl mx-auto flex items-center px-6 w-full">
        <div className="text-2xl font-bold tracking-wide flex-1" style={{ fontFamily: "'Playfair Display', serif" }}>
          <Link to="/" onClick={toggleMenu}>CraftedWebs</Link>
        </div>

        <button className="lg:hidden text-white text-3xl" onClick={toggleMenu}>
          {isMenuOpen ? <FiX /> : <FiMenu />}
        </button>

        <nav className="hidden lg:flex items-center space-x-12 mx-12">
          <Link to="/" className="text-base font-medium hover:text-gray-300 transition-all">{t("home")}</Link>
          <div className="relative">
            <button onClick={toggleServices} className="flex items-center text-base font-medium hover:text-gray-300">
              {t("services")}
              <span className={`ml-2 transition-transform ${isServicesOpen ? "rotate-180" : "rotate-0"}`}>
                {isServicesOpen ? <IoIosArrowUp /> : <IoIosArrowDown />}
              </span>
            </button>
            {isServicesOpen && (
              <div className="absolute right-0 mt-2 bg-[#8b9694] text-white shadow-lg w-48 py-2 rounded-lg">
                <ul>
                  <li><Link to="/web-design" className="block px-4 py-2 hover:bg-[#646464]" onClick={toggleMenu}>{t("websites")}</Link></li>
                  <li><Link to="/google-my-business" className="block px-4 py-2 hover:bg-[#646464]" onClick={toggleMenu}>{t("googleBusiness")}</Link></li>
                  <li><Link to="/google-ads" className="block px-4 py-2 hover:bg-[#646464]" onClick={toggleMenu}>{t("googleAds")}</Link></li>
                </ul>
              </div>
            )}
          </div>
          <Link to="/portfolio" className="text-base font-medium hover:text-gray-300" onClick={toggleMenu}>{t("portfolio")}</Link>
          <Link to="/pricing" className="text-base font-medium hover:text-gray-300" onClick={toggleMenu}>{t("pricing")}</Link>
          <Link to="/contact" className="text-base font-medium hover:text-gray-300" onClick={toggleMenu}>{t("contact")}</Link>
          
          <div className="relative">
            <button onClick={toggleLang} className="flex items-center font-medium text-base">
              <img src={language === "PL" ? plFlag : language === "EN" ? enFlag : ukrFlag} alt={language} className="w-6 h-6 mr-2" />
              {language}
              <span className="ml-2">{isLangOpen ? <IoIosArrowUp /> : <IoIosArrowDown />}</span>
            </button>
            {isLangOpen && (
              <div className="absolute top-full left-0 mt-2 bg-[#8b9694] text-white shadow-lg w-32 rounded-lg py-2">
                <ul>
                  <li onClick={() => changeLanguage("PL")} className="px-4 py-2 cursor-pointer hover:bg-[#646464]">PL</li>
                  <li onClick={() => changeLanguage("EN")} className="px-4 py-2 cursor-pointer hover:bg-[#646464]">EN</li>
                  <li onClick={() => changeLanguage("UKR")} className="px-4 py-2 cursor-pointer hover:bg-[#646464]">UKR</li>
                </ul>
              </div>
            )}
          </div>
        </nav>
      </div>
      
      {isMenuOpen && (
        <div className="lg:hidden fixed inset-0 bg-[#8b9694] text-white flex flex-col justify-center items-center z-40 p-6">
          <button className="absolute top-6 right-6 text-white text-3xl" onClick={toggleMenu}><FiX /></button>
          <nav className="flex flex-col space-y-4 text-center">
            <Link to="/" onClick={toggleMenu}>{t("home")}</Link>
            <Link to="/portfolio" onClick={toggleMenu}>{t("portfolio")}</Link>
            <Link to="/pricing" onClick={toggleMenu}>{t("pricing")}</Link>
            <Link to="/contact" onClick={toggleMenu}>{t("contact")}</Link>
            <div className="relative">
              <button onClick={toggleLang} className="flex items-center text-base">
                <img src={language === "PL" ? plFlag : language === "EN" ? enFlag : ukrFlag} alt={language} className="w-6 h-6 mr-2" />
                {language}
                <span className="ml-2">{isLangOpen ? <IoIosArrowUp /> : <IoIosArrowDown />}</span>
              </button>
              {isLangOpen && (
                <div className="absolute left-1/2 transform -translate-x-1/2 mt-2 bg-[#8b9694] text-white shadow-lg w-32 rounded-lg py-2">
                  <ul>
                    <li onClick={() => changeLanguage("PL")} className="px-4 py-2 cursor-pointer hover:bg-[#646464]">PL</li>
                    <li onClick={() => changeLanguage("EN")} className="px-4 py-2 cursor-pointer hover:bg-[#646464]">EN</li>
                    <li onClick={() => changeLanguage("UKR")} className="px-4 py-2 cursor-pointer hover:bg-[#646464]">UKR</li>
                  </ul>
                </div>
              )}
            </div>
          </nav>
        </div>
      )}
    </header>
  );
};

export default Header;




