import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom'; // Importujemy Link z react-router-dom

const CookieConsentModal = () => {
  const [isVisible, setIsVisible] = useState(false);

  // Sprawdzamy, czy użytkownik już wyraził zgodę
  useEffect(() => {
    const consent = localStorage.getItem('cookieConsent');
    if (!consent) {
      setIsVisible(true);
    }
  }, []);

  const handleAccept = () => {
    // Zapisujemy zgodę w localStorage
    localStorage.setItem('cookieConsent', 'true');
    setIsVisible(false);
  };

  const handleDecline = () => {
    setIsVisible(false);
  };

  return (
    <>
      {isVisible && (
        <div className="fixed inset-0 flex items-center justify-center bg-black bg-opacity-60 z-50">
          <div className="bg-gray-800 p-6 rounded-lg max-w-md mx-auto text-white">
            <h2 className="text-2xl font-semibold mb-4 text-green-500">Polityka Cookies i Prywatności</h2>
            <p>
              Nasza strona używa plików cookies, aby zapewnić Ci najlepsze doświadczenie. Prosimy o zapoznanie się
              z{' '}
              <Link to="/polityka-prywatnosci" className="text-green-400 hover:underline">
                Polityką Prywatności
              </Link>{' '}
              oraz{' '}
              <Link to="/regulamin" className="text-green-400 hover:underline">
                Regulaminem
              </Link>{' '}
              przed wyrażeniem zgody.
            </p>
            <p className="mt-4">
              Jeśli wyrażasz zgodę na używanie plików cookies, kliknij "Akceptuję". Możesz odrzucić cookies klikając
              "Odrzuć".
            </p>
            <div className="flex justify-between mt-6">
              <button
                onClick={handleDecline}
                className="px-6 py-2 bg-gray-600 text-white rounded-md hover:bg-gray-700 transition duration-300"
              >
                Odrzuć
              </button>
              <button
                onClick={handleAccept}
                className="px-6 py-2 bg-green-600 text-white rounded-md hover:bg-green-700 transition duration-300"
              >
                Akceptuję
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

export default CookieConsentModal;

