import React, { useEffect } from "react";
import { useTranslation } from "react-i18next";
import AOS from "aos";
import "aos/dist/aos.css";
import WebDesignImage from "./images/icons/web-design-example.jpg"; // Zmień na rzeczywisty obrazek

const WebDesign = () => {
  const { t } = useTranslation();

  useEffect(() => {
    AOS.init({ duration: 1000, once: true });
    window.scrollTo(0, 0);
  }, []);

  // Pobieranie danych jako obiekt, aby uniknąć błędu "map is not a function"
  const steps = t("webDesign.workProcess.steps", { returnObjects: true }) || [];
  const benefits = t("webDesign.benefits.list", { returnObjects: true }) || [];
  const faq = t("webDesign.faq.list", { returnObjects: true }) || [];

  return (
    <section className="min-h-screen grid grid-cols-1 lg:grid-cols-2 mt-20">
      {/* Zdjęcie po lewej stronie */}
      <div className="h-full">
        <img
          src={WebDesignImage}
          alt={t("webDesign.imageAlt")}
          className="w-full h-full object-cover"
        />
      </div>

      {/* Tekst po prawej stronie */}
      <div className="bg-gray-100 text-gray-800 p-10 lg:p-16 flex flex-col justify-center space-y-16">
        {/* Nagłówek */}
        <div>
          <div className="flex items-center mb-6">
            <div className="w-1 h-14 bg-gray-800 mr-4"></div>
            <h1 className="text-5xl font-light text-gray-800 leading-tight">
              {t("webDesign.title")}
            </h1>
          </div>
          <p className="text-xl text-gray-600 leading-relaxed">
            {t("webDesign.description")}
          </p>
        </div>

        {/* Nasze podejście */}
        <div>
          <div className="flex items-center mb-6">
            <div className="w-1 h-14 bg-gray-800 mr-4"></div>
            <h2 className="text-3xl font-light text-gray-800">
              {t("webDesign.approach.title")}
            </h2>
          </div>
          <p className="text-lg text-gray-600">{t("webDesign.approach.content")}</p>
        </div>

        {/* Etapy pracy */}
        <div>
          <div className="flex items-center mb-6">
            <div className="w-1 h-14 bg-gray-800 mr-4"></div>
            <h2 className="text-3xl font-light text-gray-800">
              {t("webDesign.workProcess.title")}
            </h2>
          </div>
          <ul className="space-y-6">
            {Array.isArray(steps) &&
              steps.map(({ step, title, description }, idx) => (
                <li key={idx} className="flex items-start space-x-4">
                  <div className="w-10 h-10 bg-gray-800 text-white flex items-center justify-center rounded-full text-lg font-bold">
                    {step}
                  </div>
                  <div>
                    <span className="font-semibold text-xl text-gray-800">{title}</span>
                    <p className="text-lg text-gray-600">{description}</p>
                  </div>
                </li>
              ))}
          </ul>
        </div>

        {/* Korzyści */}
        <div>
          <div className="flex items-center mb-6">
            <div className="w-1 h-14 bg-gray-800 mr-4"></div>
            <h2 className="text-3xl font-light text-gray-800">
              {t("webDesign.benefits.title")}
            </h2>
          </div>
          <ul className="space-y-6">
            {Array.isArray(benefits) &&
              benefits.map(({ title, description }, idx) => (
                <li key={idx} className="flex items-start space-x-4">
                  <div className="w-10 h-10 bg-gray-800 text-white flex items-center justify-center rounded-full text-lg font-bold">
                    {idx + 1}
                  </div>
                  <div>
                    <span className="font-semibold text-xl text-gray-800">{title}</span>
                    <p className="text-lg text-gray-600">{description}</p>
                  </div>
                </li>
              ))}
          </ul>
        </div>

        {/* FAQ */}
        <div>
          <div className="flex items-center mb-6">
            <div className="w-1 h-14 bg-gray-800 mr-4"></div>
            <h2 className="text-3xl font-light text-gray-800">
              {t("webDesign.faq.title")}
            </h2>
          </div>
          <ul className="space-y-6">
            {Array.isArray(faq) &&
              faq.map(({ question, answer }, idx) => (
                <li key={idx}>
                  <span className="font-semibold text-xl text-gray-800">{question}</span>
                  <p className="text-lg text-gray-600">{answer}</p>
                </li>
              ))}
          </ul>
        </div>
      </div>
    </section>
  );
};

export default WebDesign;

