import React, { useEffect } from "react";
import { useTranslation } from "react-i18next";
import AOS from "aos";
import "aos/dist/aos.css";
import TargetIcon from "./images/icons/target.jpg";

const GoogleAds = () => {
  const { t } = useTranslation();
  
  useEffect(() => {
    AOS.init({ duration: 1000, once: true });
    window.scrollTo(0, 0);
  }, []);

  // Pobieranie danych z tłumaczeń
  const title = t("googleAds1.title");
  const description = t("googleAds1.description");
  const howItWorks = t("googleAds1.howItWorks", { returnObjects: true });
  const benefits = t("googleAds1.benefits", { returnObjects: true });
  const faq = t("googleAds1.faq", { returnObjects: true });

  return (
    <section className="min-h-screen grid grid-cols-1 lg:grid-cols-2 mt-20">
      {/* Zdjęcie po lewej stronie */}
      <div className="h-full">
        <img
          src={TargetIcon}
          alt="Google Ads"
          className="w-full h-full object-cover"
        />
      </div>

      {/* Tekst po prawej stronie */}
      <div className="bg-gray-100 text-gray-800 p-10 lg:p-16 flex flex-col justify-center space-y-16">
        {/* Nagłówek */}
        <div>
          <div className="flex items-center mb-6">
            <div className="w-1 h-14 bg-gray-800 mr-4"></div>
            <h1 className="text-4xl font-light text-gray-800 leading-tight">
              {title}
            </h1>
          </div>
          <p className="text-xl text-gray-600 leading-relaxed">{description}</p>
        </div>

        {/* Jak działa nasza usługa */}
        <div>
          <div className="flex items-center mb-6">
            <div className="w-1 h-14 bg-gray-800 mr-4"></div>
            <h2 className="text-3xl font-light text-gray-800">
              {howItWorks.title}
            </h2>
          </div>
          <ul className="space-y-4">
            {Array.isArray(howItWorks.steps) &&
              howItWorks.steps.map(({ title, description }, idx) => (
                <li key={idx} className="flex items-start space-x-4">
                  <div className="w-10 h-10 bg-gray-800 text-white flex items-center justify-center rounded-full text-lg font-bold">
                    {idx + 1}
                  </div>
                  <div>
                    <span className="font-semibold text-xl text-gray-800">{title}</span>
                    <p className="text-lg text-gray-600">{description}</p>
                  </div>
                </li>
              ))}
          </ul>
        </div>

        {/* Korzyści z Google Ads */}
        <div>
          <div className="flex items-center mb-6">
            <div className="w-1 h-14 bg-gray-800 mr-4"></div>
            <h2 className="text-3xl font-light text-gray-800">{benefits.title}</h2>
          </div>
          <ul className="space-y-6">
            {Array.isArray(benefits.list) &&
              benefits.list.map(({ title, description }, idx) => (
                <li key={idx} className="flex items-start space-x-4">
                  <div className="w-10 h-10 bg-gray-800 text-white flex items-center justify-center rounded-full text-lg font-bold">
                    {idx + 1}
                  </div>
                  <div>
                    <span className="font-semibold text-xl text-gray-800">{title}</span>
                    <p className="text-lg text-gray-600">{description}</p>
                  </div>
                </li>
              ))}
          </ul>
        </div>

        {/* FAQ */}
        <div>
          <div className="flex items-center mb-6">
            <div className="w-1 h-14 bg-gray-800 mr-4"></div>
            <h2 className="text-3xl font-light text-gray-800">{faq.title}</h2>
          </div>
          <ul className="space-y-4">
            {Array.isArray(faq.questions) &&
              faq.questions.map(({ question, answer }, idx) => (
                <li key={idx}>
                  <span className="font-semibold text-xl text-gray-800">{question}</span>
                  <p className="text-lg text-gray-600">{answer}</p>
                </li>
              ))}
          </ul>
        </div>
      </div>
    </section>
  );
};

export default GoogleAds;



