import React, { useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import AOS from 'aos';
import 'aos/dist/aos.css';
import facebookIcon from './images/icons/facebook.png';
import linkedinIcon from './images/icons/linkedin.png';

const Contact = () => {
  const { t } = useTranslation();

  useEffect(() => {
    AOS.init({ duration: 1000, easing: 'ease-out', once: true });
  }, []);

  return (
    <section className="min-h-screen bg-[#8b9694] flex flex-col justify-center px-6 sm:px-12 lg:px-16 py-12">
      <div className="w-full grid grid-cols-1 lg:grid-cols-2 gap-16 items-start">
        {/* Nagłówek z kreską */}
        <div
          className="flex items-start space-x-4"
          data-aos="fade-right"
          data-aos-delay="200"
        >
          <div className="border-l-4 border-gray-800 h-16 sm:h-20"></div>
          <h2 className="text-4xl sm:text-5xl lg:text-6xl font-light text-gray-800 leading-none">
            {t('contact_info.heading')}
          </h2>
        </div>

        {/* Informacje kontaktowe */}
        <div
          className="flex flex-col space-y-12 text-gray-800"
          data-aos="fade-up"
          data-aos-delay="400"
        >
          {/* Telefon */}
          <div>
            <h3 className="text-xl sm:text-2xl lg:text-3xl font-semibold uppercase mb-2">
              {t('contact_info.phoneLabel')}
            </h3>
            <a
              href="tel:+48576564682"
              className="relative text-base sm:text-lg lg:text-xl font-light hover:underline-none group"
            >
              +48 576-564-682
              <span className="absolute left-0 bottom-[-4px] h-[2px] w-0 bg-gray-800 transition-all duration-300 ease-in-out group-hover:w-full"></span>
            </a>
          </div>

          {/* Email */}
          <div>
            <h3 className="text-xl sm:text-2xl lg:text-3xl font-semibold uppercase mb-2">
              {t('contact_info.emailLabel')}
            </h3>
            <a
              href="mailto:anastasiia.kupriianets@outlook.com"
              className="relative text-base sm:text-lg lg:text-xl font-light hover:underline-none group"
            >
              anastasiia.kupriianets@outlook.com
              <span className="absolute left-0 bottom-[-4px] h-[2px] w-0 bg-gray-800 transition-all duration-300 ease-in-out group-hover:w-full"></span>
            </a>
          </div>

          {/* Media społecznościowe */}
          <div>
            <h3 className="text-xl sm:text-2xl lg:text-3xl font-semibold uppercase mb-2">
              {t('contact_info.socialMediaLabel')}
            </h3>
            <div className="flex items-center space-x-6">
              <a
                href="https://www.facebook.com/groups/551428447858277"
                target="_blank"
                rel="noopener noreferrer"
                data-aos="fade-left"
                data-aos-delay="600"
              >
                <img
                  src={facebookIcon}
                  alt="Facebook"
                  className="w-8 sm:w-10 lg:w-12 h-8 sm:h-10 lg:h-12"
                />
              </a>
              <a
                href="https://www.linkedin.com/groups/13117822/"
                target="_blank"
                rel="noopener noreferrer"
                data-aos="fade-left"
                data-aos-delay="800"
              >
                <img
                  src={linkedinIcon}
                  alt="LinkedIn"
                  className="w-8 sm:w-10 lg:w-12 h-8 sm:h-10 lg:h-12"
                />
              </a>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default Contact;












      
