import React, { useEffect } from "react";
import { useTranslation } from "react-i18next";
import AOS from "aos";
import "aos/dist/aos.css";

const Services = () => {
  const { t } = useTranslation();

  useEffect(() => {
    AOS.init({
      duration: 1000, // Czas trwania animacji w ms
      once: true, // Animacja uruchamia się tylko raz
    });
  }, []);

  return (
    <section className="py-16 sm:py-32 bg-gray-100 text-gray-800 flex flex-col sm:flex-row w-full px-6 md:px-12 lg:px-20">
      {/* Lewa sekcja z nagłówkiem */}
      <div
        className="sm:w-1/3 flex items-start justify-start mb-12 sm:mb-0"
        data-aos="fade-right"
      >
        <div className="flex items-center">
          <div className="border-l-2 border-gray-800 h-24 sm:h-32 mr-6"></div>
          <h2 className="text-3xl sm:text-4xl md:text-5xl lg:text-6xl font-light leading-tight font-sans">
            {t("ourServices")}
          </h2>
        </div>
      </div>

      {/* Prawa sekcja z listą usług */}
      <div className="sm:w-2/3 space-y-12 sm:space-y-16 md:space-y-20">
        {/* Usługa 1 */}
        <div
          className="flex items-start"
          data-aos="fade-up"
          data-aos-delay="200"
        >
          <span className="text-5xl sm:text-6xl font-light text-gray-400 mr-6 font-playfair">
            01
          </span>
          <div>
            <h3 className="text-2xl sm:text-3xl md:text-4xl font-light mb-4 font-sans">
              {t("websiteDesign")}
            </h3>
            <p className="text-base sm:text-lg md:text-xl text-gray-600 leading-relaxed font-sans">
              {t("websiteDesignDescription")}
            </p>
          </div>
        </div>

        {/* Usługa 2 */}
        <div
          className="flex items-start"
          data-aos="fade-up"
          data-aos-delay="400"
        >
          <span className="text-5xl sm:text-6xl font-light text-gray-400 mr-6 font-playfair">
            02
          </span>
          <div>
            <h3 className="text-2xl sm:text-3xl md:text-4xl font-light mb-4 font-sans">
              {t("googleBusinessProfile")}
            </h3>
            <p className="text-base sm:text-lg md:text-xl text-gray-600 leading-relaxed font-sans">
              {t("googleBusinessProfileDescription")}
            </p>
          </div>
        </div>

        {/* Usługa 3 */}
        <div
          className="flex items-start"
          data-aos="fade-up"
          data-aos-delay="600"
        >
          <span className="text-5xl sm:text-6xl font-light text-gray-400 mr-6 font-playfair">
            03
          </span>
          <div>
            <h3 className="text-2xl sm:text-3xl md:text-4xl font-light mb-4 font-sans">
              {t("googleAdsCampaigns")}
            </h3>
            <p className="text-base sm:text-lg md:text-xl text-gray-600 leading-relaxed font-sans">
              {t("googleAdsCampaignsDescription")}
            </p>
          </div>
        </div>
      </div>
    </section>
  );
};

export default Services;























