import React, { useEffect, useState } from "react";
import { useParams, Link } from "react-router-dom";
import { useTranslation } from "react-i18next";
import AOS from "aos";
import "aos/dist/aos.css";

const ProjectDetails = ({ projects }) => {
  const { id } = useParams();
  const { t } = useTranslation();
  const project = projects.find((p) => p.id === parseInt(id));
  const [imageLoaded, setImageLoaded] = useState(false);

  useEffect(() => {
    AOS.init({ duration: 1000, easing: "ease-in-out", once: true });
    window.scrollTo(0, 0);
  }, []);

  if (!project) {
    return (
      <div className="text-center text-gray-800 py-16">
        <h1 className="text-4xl font-light">{t("project.notFound")}</h1>
        <p className="text-lg text-gray-500 mt-4">
          {t("project.returnToPortfolio")}
        </p>
      </div>
    );
  }

  return (
    <div
      className="w-full h-full flex flex-col justify-center px-6 md:px-12 pt-24"
      style={{ backgroundColor: "#8b9694" }}
      data-aos="fade-in"
    >
      <div className="w-full text-left py-8 pl-4 md:pl-12">
        <h2 className="text-3xl font-light text-gray-900 border-l-4 border-gray-700 pl-4">
          {t("project.preview")}
        </h2>
      </div>
      
      <div className="flex flex-col lg:flex-row gap-8 w-full items-center">
        <div
          className="lg:w-1/2 w-full h-[40vh] overflow-hidden relative"
          data-aos="fade-right"
        >
          <img
            src={project.detailedImage}
            alt={t(project.titleKey)}
            className={`w-full object-cover border border-gray-300 shadow-lg transition-opacity duration-700 ease-in-out ${imageLoaded ? 'opacity-100' : 'opacity-0'}`}
            onLoad={() => setImageLoaded(true)}
          />
        </div>

        <div
          className="lg:w-1/2 w-full flex flex-col justify-start items-start"
          data-aos="fade-left"
        >
          <div className="flex items-center mb-6">
            <div className="border-l-4 border-gray-500 h-8 mr-4"></div>
            <h1 className="text-3xl font-light text-gray-900">
              {t(project.titleKey)}
            </h1>
          </div>

          <p className="text-lg text-gray-700 mb-6 leading-relaxed">
            {t(project.longDescriptionKey) || t(project.descriptionKey)}
          </p>

          <div className="mb-6">
            <h2 className="text-2xl font-light text-gray-900 mb-4">
              {t("project.technologiesUsed")}
            </h2>
            <div className="flex gap-4">
              <img src={`${process.env.PUBLIC_URL}/images/react.png`} alt="React" className="w-12 h-12 object-contain" />
              <img src={`${process.env.PUBLIC_URL}/images/tailwind-css.png`} alt="Tailwind CSS" className="w-12 h-12 object-contain" />
              <img src={`${process.env.PUBLIC_URL}/images/JavaScript.png`} alt="JavaScript" className="w-12 h-12 object-contain" />
            </div>
          </div>

          <div>
            <a
              href={project.link}
              target="_blank"
              rel="noopener noreferrer"
              className="py-2 px-4 text-gray-100 font-light border border-gray-500 hover:bg-gray-700 hover:border-gray-700 transition-all duration-300"
            >
              {t("project.viewProject")}
            </a>
          </div>
        </div>
      </div>

      <div className="w-full px-8 lg:px-16 mt-16 mb-16">
        <h2 className="text-3xl font-light text-gray-900 mb-6 text-center">
          {t("project.similarProjects")}
        </h2>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-10">
          {projects
            .filter((p) => p.id !== project.id)
            .slice(0, 3)
            .map((p) => (
              <div
                key={p.id}
                className="flex flex-col items-start"
                data-aos="fade-up"
              >
                <div className="flex items-center mb-4">
                  <div className="border-l-4 border-gray-500 h-6 mr-4"></div>
                  <h3 className="text-xl font-light text-gray-900">
                    {t(p.titleKey)}
                  </h3>
                </div>
                <p className="text-sm text-gray-700 leading-relaxed mb-4">
                  {t(p.descriptionKey)}
                </p>
                <Link
                  to={`/portfolio/${p.id}`}
                  className="py-2 px-4 text-gray-100 font-light border border-gray-500 hover:bg-gray-700 hover:border-gray-700 transition-all duration-300"
                >
                  {t("project.viewMore")}
                </Link>
              </div>
            ))}
        </div>
      </div>
      
      <button
        className="fixed bottom-4 right-4 bg-gray-800 text-white py-2 px-4 rounded-full shadow-lg hover:bg-gray-600 transition-all"
        onClick={() => window.scrollTo({ top: 0, behavior: "smooth" })}
      >
        {t("project.scrollToTop")}
      </button>
    </div>
  );
};

export default ProjectDetails;
