import React, { useState } from "react";
import { useTranslation } from "react-i18next";
import emailjs from "emailjs-com";

const Pricing = () => {
  const { t } = useTranslation();

  const [formData, setFormData] = useState({
    name: "",
    email: "",
    company: "",
    nip: "",
    street: "",
    city: "",
    postalCode: "",
    phone: "",
    domain: "",
    package: "",
  });

  const [showConfirmation, setShowConfirmation] = useState(false);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value,
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();

    const templateParams = {
      companyName: formData.company,
      contactEmail: formData.email,
      message: t("pricing.form.message"),
      packageName: formData.package,
      name: formData.name,
      nip: formData.nip,
      street: formData.street,
      city: formData.city,
      postalCode: formData.postalCode,
      phone: formData.phone,
      domain: formData.domain,
    };

    emailjs
      .send(
        "service_uq45nvk",
        "template_sv51gfq",
        templateParams,
        "vgMyUXe7D-ey-o5-Y"
      )
      .then(
        (result) => {
          setShowConfirmation(true);
          console.log(result.text);
        },
        (error) => {
          console.log(error.text);
        }
      );
  };

  const handlePackageSelection = (selectedPackage) => {
    setFormData({
      ...formData,
      package: selectedPackage,
    });
    window.scrollTo(0, document.getElementById("order-form").offsetTop);
  };

  return (
    <section className="bg-[#646464] py-32 text-white font-sans">
      <div className="max-w-screen-xl mx-auto px-6 text-left">
        <h1 className="text-5xl font-light text-white mb-6 border-l-4 pl-4 border-white">
          {t("pricing1.title")}
        </h1>
        <p className="text-lg text-gray-300 mb-12 leading-relaxed">{t("pricing1.description")}</p>

        {/* Pricing Tiers */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
          {["start", "standard", "pro"].map((plan, index) => (
            <div
              key={index}
              className="bg-[#646464] w-full max-w-[600px] mx-auto p-12 border-2 border-white text-center flex flex-col justify-between rounded-none shadow-lg"
            >
              <h2 className="text-3xl font-light text-white mb-6">{t(`pricing1.plans.${plan}.title`)}</h2>
              <p className="text-lg text-gray-300 mb-6 leading-relaxed">{t(`pricing1.plans.${plan}.description`)}</p>
              <span className="text-5xl font-bold text-white mb-6">{t(`pricing1.plans.${plan}.price`)}</span>
              <ul className="text-left text-gray-300 mb-6 space-y-4 leading-relaxed">
                {Array.isArray(t(`pricing1.plans.${plan}.features`, { returnObjects: true }))
                  ? t(`pricing1.plans.${plan}.features`, { returnObjects: true }).map((feature, i) => (
                      <li key={i} className="flex items-center space-x-2">
                        <span className="text-green-400 text-xl">✔</span>
                        <span>{feature}</span>
                      </li>
                    ))
                  : null}
              </ul>
              <button
                className="bg-white text-[#646464] py-4 px-10 rounded-none hover:bg-gray-300 transition-all mt-auto font-semibold"
                onClick={() => handlePackageSelection(plan)}
              >
                {t("pricing1.selectPackage")}
              </button>
            </div>
          ))}
        </div>

        {/* Order Form */}
        <div id="order-form" className="mt-16 bg-[#646464] p-12 text-white rounded-none">
          <h2 className="text-3xl font-light text-white mb-6 border-l-4 pl-4 border-white">
            {t("pricing1.form.title")}
          </h2>
          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
              {["name", "company", "nip", "street", "city", "postalCode", "phone", "domain"].map((field) => (
                <div key={field}>
                  <label htmlFor={field} className="block text-lg text-white mb-2">
                    {t(`pricing1.form.${field}`)}
                  </label>
                  <input
                    type="text"
                    id={field}
                    name={field}
                    value={formData[field]}
                    onChange={handleChange}
                    required
                    placeholder={t(`pricing1.form.${field}`)}
                    className="w-full p-4 bg-[#505050] text-white border-2 border-white rounded-none focus:outline-none focus:ring-2 focus:ring-gray-300"
                  />
                </div>
              ))}
              <div>
                <label htmlFor="package" className="block text-lg text-white mb-2">
                  {t("pricing1.form.selectPackage")}
                </label>
                <select
                  id="package"
                  name="package"
                  value={formData.package}
                  onChange={handleChange}
                  required
                  className="w-full p-4 bg-[#505050] text-white border-2 border-white rounded-none focus:outline-none focus:ring-2 focus:ring-gray-300"
                >
                  <option value="">{t("pricing1.form.selectPackagePlaceholder")}</option>
                  {["start", "standard", "pro"].map((plan) => (
                    <option key={plan} value={plan}>
                      {t(`pricing1.plans.${plan}.title`)}
                    </option>
                  ))}
                </select>
              </div>
            </div>

            <button
              type="submit"
              className="w-full py-4 px-10 bg-white text-[#646464] rounded-none hover:bg-gray-300 transition-all font-semibold"
            >
              {t("pricing1.form.submit")}
            </button>
          </form>
        </div>

        {/* Confirmation message */}
        {showConfirmation && (
          <div className="mt-8 text-center text-xl font-semibold text-white">
            <p>{t("pricing1.form.confirmation")}</p>
          </div>
        )}
      </div>
    </section>
  );
};

export default Pricing;


