import React from "react";
import { Link } from "react-router-dom";
import { useTranslation } from "react-i18next";

const Portfolio = ({ projects }) => {
  const { t } = useTranslation();

  return (
    <div className="portfolio-container" style={{ backgroundColor: "#8b9694", paddingTop: "10rem", paddingBottom: "4rem", paddingLeft: "2rem", paddingRight: "2rem" }}>
      <div className="flex items-center mb-16">
        <div className="w-1 h-10 bg-white mr-4"></div>
        <h1 className="text-5xl font-light text-left text-white" style={{ fontFamily: "Work Sans" }}>
          {t("portfolio1.ourProjects")}
        </h1>
      </div>
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-12">
        {projects.map((project, index) => (
          <div
            key={project.id}
            className="portfolio-item bg-transparent border border-gray-300 text-center p-8 flex flex-col justify-between hover:shadow-lg transition-shadow duration-300"
          >
            {/* Numer projektu */}
            <span
              className="text-4xl font-bold mb-4"
              style={{ fontFamily: "Playfair Display", color: "white" }}
            >
              {String(index + 1).padStart(2, "0")}
            </span>
            {/* Obrazek */}
            <div className="relative w-full h-48 overflow-hidden">
              <img
                src={project.image}
                alt={project.title}
                className="w-full h-48 object-cover mb-6 opacity-0 transition-opacity duration-700 ease-in-out"
                onLoad={(e) => e.target.classList.add('opacity-100')}
              />
            </div>
            {/* Tytuł */}
            <h2
              className="text-2xl font-semibold mb-4"
              style={{ fontFamily: "Work Sans", color: "white" }}
            >
              {t(project.titleKey)}
            </h2>
            {/* Opis */}
            <p className="text-white mb-6" style={{ fontFamily: "Work Sans" }}>
              {t(project.descriptionKey)}
            </p>
            {/* Przycisk */}
            <Link
              to={`/portfolio/${project.id}`}
              className="text-white border border-white py-2 px-6 hover:bg-white hover:text-gray-800 transition-colors duration-300"
              style={{ fontFamily: "Work Sans" }}
            >
              {t("portfolio1.seeMore")}
            </Link>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Portfolio;


