import React from "react";
import { Link } from "react-router-dom";
import { useTranslation } from "react-i18next";

const Portfolio = ({ projects = [] }) => {
  const { t } = useTranslation();

  // Sprawdzamy, czy dane są dostępne
  if (!projects || projects.length === 0) {
    return (
      <div
        className="py-16 sm:py-32 text-gray-100 text-center"
        style={{ backgroundColor: "#8b9695", minHeight: "100vh" }}
      >
        <h2 className="text-4xl sm:text-5xl font-light">{t("noProjects")}</h2>
      </div>
    );
  }

  return (
    <div
      className="py-16 sm:py-32"
      style={{ backgroundColor: "#8b9695", minHeight: "100vh" }}
    >
      {/* Nagłówek sekcji */}
      <div className="flex items-center mb-12 sm:mb-20 px-6 sm:px-16">
        <div className="border-l-4 border-gray-700 h-16 sm:h-32 mr-6 sm:mr-8"></div>
        <h2 className="text-4xl sm:text-5xl md:text-6xl font-light leading-tight text-gray-100 font-sans">
          {t("ourProjects")}
        </h2>
      </div>

      {/* Siatka projektów */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8 max-w-7xl mx-auto px-6 sm:px-16">
        {projects.slice(0, 3).map((project, index) => (
          <div
            key={index}
            className="flex flex-col items-start bg-transparent p-6 hover:opacity-90 transition-opacity duration-500 ease-in-out h-full"
          >
            {/* Numer projektu */}
            <span className="text-3xl sm:text-4xl font-light text-gray-300 mb-4 font-playfair">
              {index + 1 < 10 ? `0${index + 1}` : index + 1}
            </span>

            {/* Obrazek projektu */}
            <div className="relative w-full mb-6">
              <div className="aspect-w-3 aspect-h-4 bg-gray-500">
                <img
                  src={project.image || "https://via.placeholder.com/300"}
                  alt={project.title || t("unknownProject")}
                  className="w-full h-full object-contain"
                />
              </div>
            </div>

            {/* Tytuł projektu */}
            <h3 className="text-xl sm:text-2xl font-light text-gray-100 mb-6 font-sans">
              {project.title || t("unknownProject")}
            </h3>

            {/* Opis projektu */}
            <p className="text-base sm:text-lg md:text-xl text-gray-300 font-light mb-4 font-sans h-28 overflow-hidden">
              {project.description || t("noDescription")}
            </p>

            {/* Przycisk z linkiem do FullScreenPage */}
            <div className="mt-auto">
              <Link
                to={project.id ? `/project/${project.id}` : "#"}
                className="border border-gray-100 text-gray-100 px-4 sm:px-6 py-2 sm:py-3 text-sm sm:text-base font-light hover:bg-gray-100 hover:text-gray-800 transition-all duration-300 font-sans"
              >
                {t("seeMore")}
              </Link>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Portfolio;








































































