import React, { useEffect } from "react";
import { Link } from "react-router-dom";
import { useTranslation } from "react-i18next";
import AOS from "aos";
import "aos/dist/aos.css";
import checkIcon from "./images/icons/plus.png"; 
import korzysciImage from "./images/icons/benefits.jpg"; 
import Projects from "./Project"; 
import Pricing from "./Pricing"; 

const OurServices = () => {
  const { t } = useTranslation();

  useEffect(() => {
    AOS.init({
      duration: 1200,
      once: true,
      easing: "ease-out-cubic",
    });
  }, []);

  const projects = [
    {
      id: 1,
      title: "BELISSIMA",
      description: t("projects1.belissima.description"),
      longDescription: t("projects1.belissima.longDescription"),
      image: `${process.env.PUBLIC_URL}/images/strona_firmowa_screen.png`,
      detailedImage: `${process.env.PUBLIC_URL}/images/screenshot-ananasika_github_io_Strona_firmowa_.png`,
      link: "/project/1",
      link1: "https://ananasika.github.io/Strona-firmowa/",
    },
    {
      id: 2,
      title: "RealEstate",
      description: t("projects1.realestate.description"),
      longDescription: t("projects1.realestate.longDescription"),
      image: `${process.env.PUBLIC_URL}/images/ananasika.github.io_Finance_.png`,
      detailedImage: `${process.env.PUBLIC_URL}/images/Finance_screen.png`,
      link: "https://ananasika.github.io/drone-product-page/",
    },  
    {
      id: 3,
      title: "VisionLens",
      description: t("projects1.visionlens.description"),
      longDescription: t("projects1.visionlens.longDescription"),
      image: `${process.env.PUBLIC_URL}/images/ananasika.github.io_visionlens_.png`,
      detailedImage: `${process.env.PUBLIC_URL}/images/visionlens_screen.png`,
      link: "/project/3",
      link1: "https://ananasika.github.io/portfolio-photographer/",
    },
  ];

  return (
    <section className="pt-32 sm:pt-40 pb-0 text-gray-800 flex flex-col w-full px-0 font-[Work Sans] bg-[#8b9694] md:pt-40 sm:pt-32 xs:pt-48">
      {/* Sekcja główna */}
      <div className="text-center mb-16" data-aos="fade-up">
        <h1 className="text-4xl sm:text-5xl font-bold text-gray-900">
          {t("our_Services.mainHeading")}
        </h1>
        <p className="mt-6 text-lg sm:text-xl text-gray-700 max-w-3xl mx-auto">
          {t("our_Services.mainDescription")}
        </p>
      </div>

      {/* Kluczowe korzyści */}
      <div className="relative w-full bg-[#1e2122] text-white py-0 flex flex-col lg:flex-row items-center min-h-screen" data-aos="fade-up">
        <div className="w-full lg:w-1/2 h-screen">
          <img src={korzysciImage} alt={t("our_Services.benefitsImageAlt")} className="w-full h-full object-cover" />
        </div>
        <div className="relative z-10 px-6 sm:px-16 flex flex-col justify-center h-full text-center lg:text-left mt-8 lg:mt-0 w-full lg:w-1/2">
          <h2 className="text-3xl sm:text-4xl font-light text-white mb-6">
            {t("our_Services.benefitsHeading")}
          </h2>
          <div className="space-y-6 text-lg">
            {['benefit1', 'benefit2', 'benefit3', 'benefit4'].map((benefit, index) => (
              <div key={index} className="flex items-center gap-4" data-aos="fade-left" data-aos-delay={index * 200}>
                <img src={checkIcon} alt="Check" className="w-6 h-6" />
                <span>{t(`our_Services.${benefit}`)}</span>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Sekcja Projektów */}
      <Projects projects={projects} />
      <Pricing/>

      {/* CTA na końcu */}
      <div className="py-16 text-center bg-[#1e2122] text-white flex flex-col items-center px-0" data-aos="zoom-in">
        <h2 className="text-4xl sm:text-5xl font-light mb-6">
          {t("our_Services.ctaHeading")}
        </h2>
        <p className="text-lg sm:text-xl max-w-3xl mx-auto mb-8">
          {t("our_Services.ctaDescription")}
        </p>
        <Link
          to="/contact"
          className="bg-white text-gray-900 px-6 py-3 text-lg font-semibold rounded-full hover:bg-gray-300 transition-all duration-300"
        >
          {t("our_Services.contactButton")}
        </Link>
      </div>
    </section>
  );
};

export default OurServices;
