import React, { useEffect } from "react";
import AOS from "aos";
import "aos/dist/aos.css";

const About = () => {
  useEffect(() => {
    AOS.init({ duration: 1000, once: true });
  }, []);

  return (
    <section
      className="min-h-screen flex flex-col lg:flex-row text-white"
      style={{ backgroundColor: "#646464" }}
    >
      {/* Sekcja z tekstem */}
      <div className="lg:w-1/2 w-full flex flex-col justify-start lg:justify-center px-6 sm:px-12 md:px-16 pt-8 sm:pt-12 pb-6">
        <div className="border-l-4 border-white pl-4 mb-6">
          <h1 className="text-3xl sm:text-4xl md:text-5xl font-light leading-tight font-sans">
            <span className="font-playfair">CraftedWebs</span>:<br /> Tworzymy
            strony, które działają
          </h1>
        </div>
        <p className="text-base sm:text-lg md:text-xl text-gray-200 leading-relaxed mb-4 font-sans">
          Specjalizujemy się w projektowaniu nowoczesnych i funkcjonalnych stron
          internetowych. Nasze strony są responsywne, szybkie i łatwe w obsłudze,
          dzięki czemu Twoi klienci znajdą to, czego szukają.
        </p>
        <p className="text-base sm:text-lg md:text-xl text-gray-200 leading-relaxed mb-4 font-sans">
          Każdy projekt jest dopasowany do potrzeb Twojej firmy. Dbamy o estetykę,
          intuicyjność i optymalizację, aby Twoja strona przyciągała więcej
          odwiedzających i zachęcała ich do działania.
        </p>
        <p className="text-base sm:text-lg md:text-xl text-gray-200 leading-relaxed font-sans">
          W <span className="font-playfair">CraftedWebs</span> wierzymy, że dobra
          strona internetowa to inwestycja w rozwój Twojego biznesu. Dlatego
          oferujemy kompleksowe rozwiązania – od projektu po wdrożenie.
        </p>
      </div>

      {/* Sekcja z wideo */}
      <div
        className="lg:w-1/2 w-full flex justify-center lg:justify-end items-center lg:items-stretch"
        data-aos="fade-left"
        style={{
          minHeight: "100vh",
          padding: "0", // Usunięcie marginesów na dużych ekranach
        }}
      >
        <video
          className="w-full lg:w-auto h-auto lg:h-full object-cover"
          controls
          style={{
            padding: "0", // Na dużych ekranach brak odstępów
            margin: "0",
            borderRadius: "0", // Na dużych ekranach brak zaokrągleń
          }}
        >
          <source
            src={`${process.env.PUBLIC_URL}/videos/crafted-webs-intro.mp4`} // Zmień na rzeczywistą ścieżkę do wideo
            type="video/mp4"
          />
          Twoja przeglądarka nie obsługuje elementu wideo.
        </video>
      </div>
    </section>
  );
};

export default About;



















